(function(){var st=document.getElementById('pyt-css');if(!st){st=document.createElement('style');st.id='pyt-css';st.textContent="/* Тренажёр КР по Python, встроен в конспект Учёбы: цвета берутся из переменных темы Учёбы */\n.pyt{--a1:var(--accent);--a2:var(--accent);margin:18px 0 8px;font-family:var(--sans)}\n.prose .pyt h2,.prose .pyt h3,.prose .pyt h4,.prose .pyt h5{font-family:var(--sans);font-style:normal;text-transform:none;letter-spacing:0;text-align:left;color:var(--fg);padding:0;border:0;background:none;display:block;line-height:1.25}\n.prose .pyt h2:before,.prose .pyt h2:after,.prose .pyt h3:before,.prose .pyt h3:after,.prose .pyt h4:before,.prose .pyt h4:after{content:none!important;display:none}\n.prose .pyt h2{font-size:1.3em;font-weight:700;margin:0 0 8px}\n.prose .pyt h3{font-size:1.1em;font-weight:700;margin:2px 0 6px}\n.prose .pyt h4{font-size:.78em;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin:14px 0 4px}\n.prose .pyt h5{font-size:1em;font-weight:700;margin:0 0 6px}\n.prose .pyt p{text-indent:0}.prose .pyt p:first-child:first-letter{all:unset}\n.prose .pyt pre{margin:6px 0;white-space:pre-wrap}\n.prose .pyt table{width:100%}\n.pm{font:13px/1.35 ui-monospace,'SF Mono','JetBrains Mono',Menlo,Consolas,monospace}\n.pyt code,.pyt pre,.pyt textarea{font-family:ui-monospace,'SF Mono','JetBrains Mono',Menlo,Consolas,monospace}\n.pbtn{height:42px;padding:0 18px;border:1px solid var(--line);border-radius:999px;background:var(--surface);color:var(--fg);font:500 14px/1 'IBM Plex Sans',system-ui,sans-serif;cursor:pointer;white-space:nowrap}\n.pbtn:hover:not(:disabled){border-color:var(--faint)}\n.pbtn:disabled{opacity:.45;cursor:not-allowed}\n.pbtn.pri{background:var(--a2);border-color:var(--a2);color:var(--surface);font-weight:600}\n.pbtn.pri:hover:not(:disabled){filter:brightness(1.07)}\n.pbtn.sm{height:34px;padding:0 13px;font-size:13px}\n.pbtn.big{height:50px;padding:0 30px;font-size:16px}\n/* меню */\n.pmodes{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:12px;margin:18px 0 6px}\n.pmode{text-align:left;padding:15px 17px;border:1px solid var(--line);border-radius:16px;background:var(--surface);color:var(--fg);cursor:pointer;display:flex;flex-direction:column;gap:5px;transition:border-color .15s}\n.pmode b{font:600 16px/1.2 'IBM Plex Sans',system-ui,sans-serif}.pmode small{color:var(--muted);font:400 13.5px/1.4 'IBM Plex Sans',system-ui,sans-serif}\n.pmode:hover{border-color:var(--faint)}.pmode.on{border-color:var(--a2);box-shadow:inset 0 -3px 0 var(--a2)}\n.ph3{margin:26px 0 10px;font:600 12px/1.2 'IBM Plex Sans',sans-serif;letter-spacing:.09em;text-transform:uppercase;color:var(--faint)}\n.pvars{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:12px}\n.pvar{display:flex;flex-direction:column;gap:6px;padding:16px 17px;border:1px solid var(--line);border-radius:16px;background:var(--surface)}\n.pvar h3{margin:0;font:600 18px/1.2 'IBM Plex Sans',system-ui,sans-serif;display:flex;align-items:center;gap:10px}\n.pvar h3 i{display:inline-grid;place-items:center;width:34px;height:34px;border-radius:50%;background:color-mix(in srgb,var(--a2) 14%,var(--surface));color:var(--a2);font:700 16px 'IBM Plex Sans',sans-serif;font-style:normal}\n.pvar p{margin:0;color:var(--muted);font:400 14px/1.4 'IBM Plex Sans',system-ui,sans-serif}\n.pvar .pp{display:flex;gap:4px;flex-wrap:wrap;margin:4px 0 8px}\n.pdot{width:22px;height:8px;border-radius:4px;background:var(--line)}.pdot.ok{background:#2a9d5c}.pdot.bad{background:#d9534f}\n.pvar .prow{display:flex;gap:8px;flex-wrap:wrap;margin-top:auto}\n.pnote{margin:18px 0 0;padding:12px 15px;border:1px dashed var(--line);border-radius:12px;color:var(--muted);font:400 13.5px/1.5 'IBM Plex Sans',system-ui,sans-serif}\n/* верхняя панель */\n.pbar{display:flex;align-items:center;gap:10px 14px;flex-wrap:wrap;margin:16px 0 10px}\n.pbar .ptt{font:600 16px 'IBM Plex Sans',sans-serif}\n.pbar .pspc{flex:1}\n.pbadge{padding:5px 11px;border-radius:999px;border:1px solid var(--line);font:500 12.5px 'IBM Plex Sans',sans-serif;color:var(--muted)}\n.pbadge.ex{border-color:var(--a1);color:var(--a1)}\n.ptimer{font:600 18px ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums}\n.ptimer.low{color:#d9534f}\n.pscore{font:500 13.5px 'IBM Plex Sans',sans-serif;color:var(--muted)}.pscore b{color:var(--fg)}\n.ptabs{display:flex;gap:6px;flex-wrap:wrap;margin:0 0 14px}\n.ptab{min-width:46px;height:44px;padding:0 10px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--fg);cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;font:600 15px/1 'IBM Plex Sans',sans-serif;position:relative}\n.ptab small{font:400 10.5px/1 'IBM Plex Sans',sans-serif;color:var(--faint)}\n.ptab.cur{border-color:var(--a2);box-shadow:inset 0 -3px 0 var(--a2)}\n.ptab.ok{background:color-mix(in srgb,#2a9d5c 16%,var(--surface))}\n.ptab.ok::after{content:\"✓\";position:absolute;top:2px;right:5px;font-size:11px;color:#2a9d5c}\n.ptab.bad::after{content:\"✗\";position:absolute;top:2px;right:5px;font-size:11px;color:#d9534f}\n/* сетка задачи */\n.pgrid{display:grid;grid-template-columns:minmax(0,1fr);gap:18px;align-items:start}\n@media(min-width:1000px){.pgrid{grid-template-columns:minmax(0,5fr) minmax(0,6fr)}.ptask{position:sticky;top:calc(var(--hdr,0px) + 14px);max-height:calc(100vh - var(--hdr,0px) - 30px);overflow:auto}main:has(.pyt.inwork){max-width:min(1240px,100%)!important}.note-wrap:has(.pyt.inwork){grid-template-columns:minmax(0,1fr)!important}.note:has(.pyt.inwork){max-width:100%!important}.pqb,.pqc{display:none!important}}\n.pqc{display:none;margin:0 0 10px}\n.pqb{position:sticky;top:54px;z-index:6;align-self:flex-end;background:var(--surface)}\n#pqs{position:fixed;inset:0;z-index:98;background:rgba(0,0,0,.42);display:flex;align-items:flex-start;justify-content:center;padding:54px 8px 8px;box-sizing:border-box}\n#pqs .ptask{width:100%;max-width:680px;max-height:100%;overflow:auto;box-sizing:border-box;box-shadow:0 14px 44px rgba(0,0,0,.4);position:static}\n#pqs .pqc{display:inline-block!important}\n.ptask{padding:18px 20px;border:1px solid var(--line);border-radius:16px;background:var(--surface)}\n.ptask h2{margin:0 0 6px;font:600 21px/1.25 'IBM Plex Sans',system-ui,sans-serif}\n.ptask .pmeta{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 12px}\n.ptask .pmeta span{padding:3px 10px;border-radius:999px;border:1px solid var(--line);font:500 12px 'IBM Plex Sans',sans-serif;color:var(--muted)}\n.ptask .pmeta span.pts{border-color:var(--a2);color:var(--a2)}\n.ptask p{margin:0 0 10px;font:400 15.5px/1.6 'Literata',Georgia,serif}\n.ptask p code,.psol li code,.psol p code,.pout-tip code{padding:1px 6px;border-radius:6px;background:color-mix(in srgb,var(--fg) 7%,var(--surface));font-size:.9em}\n.ptask h4{margin:14px 0 4px;font:600 11.5px/1.2 'IBM Plex Sans',sans-serif;letter-spacing:.08em;text-transform:uppercase;color:var(--faint)}\n.pex{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:0 0 8px}\n.pex>div{min-width:0}\n.pex small{display:block;margin:0 0 3px;font:500 11.5px 'IBM Plex Sans',sans-serif;color:var(--faint)}\n.pbk{margin:0;padding:9px 11px;border:1px solid var(--line);border-radius:10px;background:color-mix(in srgb,var(--fg) 4%,var(--surface));font:13px/1.45 ui-monospace,'SF Mono',Menlo,Consolas,monospace;white-space:pre;overflow:auto;color:var(--fg);min-height:2.2em}\n/* редактор */\n.pcode{min-width:0;display:flex;flex-direction:column;gap:10px}\n.ppre{margin:0;border-radius:12px 12px 0 0}\n.ppre-l{font:500 11.5px 'IBM Plex Sans',sans-serif;color:var(--faint);margin:0 0 -4px}\n#pcode{width:100%;min-height:290px;resize:vertical;padding:12px 14px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--fg);font:14px/1.5 ui-monospace,'SF Mono',Menlo,Consolas,monospace;tab-size:4;white-space:pre;overflow:auto;box-sizing:border-box}\n#pcode:focus{outline:2px solid color-mix(in srgb,var(--a2) 45%,transparent);outline-offset:0;border-color:var(--a2)}\n.pkeys{display:flex;gap:6px;flex-wrap:wrap}\n.pact{display:flex;gap:8px;flex-wrap:wrap}\n.pin{border:1px solid var(--line);border-radius:12px;padding:0 12px;background:var(--surface)}\n.pin summary{padding:10px 0;cursor:pointer;font:500 13.5px 'IBM Plex Sans',sans-serif;color:var(--muted)}\n.pin textarea{width:100%;min-height:90px;margin:0 0 12px;padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:color-mix(in srgb,var(--fg) 4%,var(--surface));color:var(--fg);font:13px/1.45 ui-monospace,Menlo,Consolas,monospace;box-sizing:border-box}\n.pst{font:500 12.5px 'IBM Plex Sans',sans-serif;color:var(--faint);min-height:1.2em}\n.pst.err{color:#d9534f}\n/* результаты */\n.pout{display:flex;flex-direction:column;gap:10px}\n.pbox{border:1px solid var(--line);border-radius:12px;padding:12px 14px;background:var(--surface)}\n.pbox h5{margin:0 0 6px;font:600 13px 'IBM Plex Sans',sans-serif}\n.pbox.ok{border-color:#2a9d5c;background:color-mix(in srgb,#2a9d5c 9%,var(--surface))}\n.pbox.bad{border-color:#d9534f;background:color-mix(in srgb,#d9534f 7%,var(--surface))}\n.pbox.err{border-color:#d9534f}\n.pbox .pbk{background:var(--bg)}\n.ptests{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 8px}\n.pt{padding:4px 10px;border-radius:999px;font:600 12px 'IBM Plex Sans',sans-serif;border:1px solid var(--line);color:var(--muted)}\n.pt.ok{border-color:#2a9d5c;color:#2a9d5c}.pt.bad{border-color:#d9534f;color:#d9534f}\n.pdiff{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:8px 0}\n.pdiff small{display:block;margin:0 0 3px;font:500 11.5px 'IBM Plex Sans',sans-serif;color:var(--faint)}\n.pdiff .pbk .bad{background:color-mix(in srgb,#d9534f 22%,transparent);display:inline-block;min-width:100%}\n.pout-tip{margin:8px 0 0;font:400 14px/1.5 'IBM Plex Sans',system-ui,sans-serif}\n.pout-tip ul{margin:4px 0 0;padding-left:20px}\n/* разбор */\n.psol{margin-top:18px;padding:18px 20px;border:1px solid var(--a2);border-radius:16px;background:var(--surface)}\n.psol h3{margin:0 0 10px;font:600 19px 'IBM Plex Sans',sans-serif}\n.psol h4{margin:16px 0 6px;font:600 11.5px 'IBM Plex Sans',sans-serif;letter-spacing:.08em;text-transform:uppercase;color:var(--faint)}\n.psol p,.psol li{font:400 15.5px/1.6 'Literata',Georgia,serif}\n.psol ol,.psol ul{margin:0;padding-left:22px}.psol li{margin:0 0 5px}\n.psol .ptrace{padding:10px 13px;border-radius:10px;background:color-mix(in srgb,var(--fg) 5%,var(--surface));margin:0}\n.psol .prow{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}\n.hk{color:var(--a1);font-weight:600}.hs{color:#2a9d5c}.hn{color:#c77d1a}.hc{color:var(--faint);font-style:italic}.hb{color:#6a5acd}\n/* итог */\n.ptbl{width:100%;border-collapse:collapse;margin:8px 0 16px;font:400 14.5px 'IBM Plex Sans',sans-serif}\n.ptbl th,.ptbl td{padding:9px 10px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}\n.ptbl th{font-weight:600;color:var(--faint);font-size:12px;letter-spacing:.05em;text-transform:uppercase}\n.ptblw{overflow-x:auto}\n.pbig{font:700 44px/1 'IBM Plex Sans',sans-serif;margin:6px 0}\n.pbig small{font:500 16px 'IBM Plex Sans',sans-serif;color:var(--muted)}\n@media(max-width:560px){.pex,.pdiff{grid-template-columns:1fr}.ptask{padding:15px 15px}.psol{padding:15px}.pbtn{height:44px}.pbtn.sm{height:36px}#pcode{font-size:16px;min-height:260px}}\n@media(prefers-reduced-motion:reduce){.pmode,.pbtn{transition:none}}\n\n.ptask h2{text-align:left!important;font:600 20px/1.25 'IBM Plex Sans',system-ui,sans-serif!important;padding:0!important;margin:0 0 6px!important;font-style:normal!important;letter-spacing:0!important;text-transform:none!important}\n.ptask h4{text-align:left!important;font:600 11.5px/1.2 'IBM Plex Sans',system-ui,sans-serif!important;font-style:normal!important;letter-spacing:.08em!important;text-transform:uppercase!important;margin:14px 0 4px!important;padding:0!important;color:var(--faint)!important}\n";document.head.appendChild(st)}})();
var PYD=[{"id":"A","name":"Вариант А","sub":"Кино и кафе","tasks":[{"id":"A1","n":1,"pts":0.5,"title":"Билет в кино","topics":"if / elif / else, not in, or","text":"В окне уже заданы список `sessions` и три фразы: `none_msg`, `cheap_msg`, `full_msg`. Вводятся время сеанса и возраст зрителя.\n\nЕсли такого сеанса нет в списке, напечатайте `none_msg`. Если сеанс есть и зрителю меньше 12 лет или 60 и больше, напечатайте `cheap_msg`. Во всех остальных случаях напечатайте `full_msg`.","fin":"Первая строка — время сеанса, вторая — возраст (целое число).","fout":"Одна из трёх фраз.","pre":"sessions = ['10:00', '14:00', '18:00']\nnone_msg = 'Такого сеанса нет'\ncheap_msg = 'Льготный билет'\nfull_msg = 'Полный билет'","tests":[{"i":"10:00\n8","o":"Льготный билет"},{"i":"14:00\n30","o":"Полный билет"},{"i":"20:00\n10","o":"Такого сеанса нет"},{"i":"18:00\n60","o":"Льготный билет"},{"i":"10:00\n12","o":"Полный билет"},{"i":"14:00\n59","o":"Полный билет"},{"i":"18:00\n11","o":"Льготный билет"}],"sol":"time = input()\nage = int(input())\n\nif time not in sessions:\n    print(none_msg)\nelif age < 12 or age >= 60:\n    print(cheap_msg)\nelse:\n    print(full_msg)","hint":"Сначала отсеките несуществующие сеансы (`not in`), потом проверьте возраст через `or`, остальное — `else`. Возраст — строка, нужен `int`.","idea":"Три исхода — цепочка `if / elif / else`: нет сеанса; льгота по возрасту; полный билет.","steps":["`time = input()` читает сеанс, `age = int(input())` читает возраст и сразу делает его числом.","`time not in sessions` — первая проверка: если сеанса нет, возраст не важен.","`age < 12 or age >= 60` — льгота, если верно **хотя бы одно** из двух условий.","`else` — полный билет."],"mist":["Написали `age < 12 and age >= 60`: оба условия сразу не бывают верны, льготы не будет ни у кого.","Забыли `int(...)`: сравнение строки с числом — ошибка `TypeError`.","Границы: 12 лет уже платят полностью, 60 лет — уже льгота; перепутали `<` и `<=`."],"trace":""},{"id":"A2","n":2,"pts":1,"title":"Недорогие блюда","topics":"while True, break, split, список","text":"Вводятся строки вида `блюдо:цена` (цена — целое число), пока не будет введено слово `END`.\n\nНапечатайте список блюд, которые стоят **не дороже 300**, в порядке ввода. Если таких нет, напечатайте пустой список.","fin":"Строки `блюдо:цена`, последняя строка — `END`.","fout":"Список блюд в квадратных скобках, как печатает `print(список)`.","pre":"","tests":[{"i":"Борщ:250\nСтейк:900\nСуп:300\nEND","o":"['Борщ', 'Суп']"},{"i":"END","o":"[]"},{"i":"Пицца:450\nСалат:301\nEND","o":"[]"},{"i":"Чай:80\nКофе:120\nПирог:200\nEND","o":"['Чай', 'Кофе', 'Пирог']"},{"i":"Паста:300\nEND","o":"['Паста']"}],"sol":"cheap = []\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    dish, price = line.split(':')\n    if int(price) <= 300:\n        cheap.append(dish)\n\nprint(cheap)","hint":"Список создайте до цикла. Строку режьте по двоеточию: `dish, price = line.split(\":\")`. Цена — строка, нужен `int`. «Не дороже» — это `<=`.","idea":"Читаем строки в бесконечном цикле, на слове `END` выходим через `break`, остальное разбираем и фильтруем.","steps":["`cheap = []` создаём **до** цикла, иначе список обнулялся бы на каждой строке.","`while True:` — читаем, пока сами не прервём цикл.","`line == \"END\"` → `break`: выходим, не обрабатывая слово `END`.","`dish, price = line.split(\":\")` — две части строки в две переменные.","`int(price) <= 300` — «не дороже» включает ровно 300."],"mist":["Список создан внутри цикла — в конце останется только последнее блюдо.","Не сделали `int(price)`: сравнение строки с числом — ошибка `TypeError`.","Поставили `<`: блюдо ровно за 300 пропадёт."],"trace":""},{"id":"A3","n":3,"pts":0.5,"title":"Список гостей","topics":"split(\", \"), in, remove, append","text":"В первой строке имена гостей через «запятая + пробел». Во второй — имя одного человека.\n\nЕсли он уже в списке, он отменил бронь — удалите его из списка. Если его нет — добавьте в конец. Напечатайте список.","fin":"Первая строка — имена через `, `. Вторая — одно имя.","fout":"Список имён в квадратных скобках.","pre":"","tests":[{"i":"Аня, Борис, Вера\nБорис","o":"['Аня', 'Вера']"},{"i":"Аня, Борис\nГлеб","o":"['Аня', 'Борис', 'Глеб']"},{"i":"Дима\nДима","o":"[]"},{"i":"Зоя, Ира\nзоя","o":"['Зоя', 'Ира', 'зоя']"},{"i":"Олег, Пётр, Рита\nРита","o":"['Олег', 'Пётр']"}],"sol":"guests = input().split(', ')\nname = input()\n\nif name in guests:\n    guests.remove(name)\nelse:\n    guests.append(name)\n\nprint(guests)","hint":"Строку с именами разбейте `split(\", \")`. Если имя есть (`in`) — `remove`, иначе — `append`.","idea":"Превращаем строку в список и, смотря по наличию имени, удаляем его или добавляем.","steps":["`input().split(\", \")` — строка превращается в список имён.","`name in guests` — истина, если человек уже есть в списке.","`remove` удаляет, `append` добавляет в конец; оба меняют сам список.","`print(guests)` — один раз, после `if`."],"mist":["`split()` без аргумента: запятые останутся в кусках имён.","`remove` для имени, которого нет, даёт `ValueError` — поэтому сначала проверяем `in`.","Результат `append` или `remove` присвоили переменной: получится `None`."],"trace":""},{"id":"A4","n":4,"pts":1,"title":"Хорошие фильмы","topics":"два списка, range(len()), float","text":"В первой строке названия фильмов через пробел, во второй — их оценки (числа, бывают дробные) в том же порядке. В третьей — оценка, выше которой фильм считается хорошим.\n\nНапечатайте названия фильмов с оценкой **строго выше** этой, каждое с новой строки.","fin":"Три строки: названия, оценки, граница.","fout":"Названия по одному на строке или пустой вывод.","pre":"","tests":[{"i":"Дюна Титаник Хатико Зелёнка\n8.5 7.9 8.1 6.4\n8","o":"Дюна\nХатико"},{"i":"А Б\n7 7.5\n7.5","o":""},{"i":"Один\n9\n8.9","o":"Один"},{"i":"Х У Ф\n5 6 7\n7","o":""},{"i":"Лента Кино\n8.0 8.0\n7","o":"Лента\nКино"}],"sol":"films = input().split()\nmarks = input().split()\nlimit = float(input())\n\nfor i in range(len(films)):\n    if float(marks[i]) > limit:\n        print(films[i])","hint":"Фильмы и оценки лежат в двух списках, связь — одинаковый номер. Переберите номера через `range(len(...))`. Оценки — строки, нужен `float`.","idea":"Идём по номерам: по номеру берём и фильм, и оценку, сравниваем оценку с границей.","steps":["`films` и `marks` — списки **строк**; оценку берём как `float(marks[i])`.","`range(len(films))` — номера 0, 1, 2, …","`float(marks[i]) > limit` — «строго выше», то есть `>`.","Печатаем `films[i]` — фильм с тем же номером."],"mist":["`>=` вместо `>`: фильм ровно с граничной оценкой попадёт зря.","Использовали `int` для оценки `8.5`: будет `ValueError`.","Напечатали `marks[i]` вместо `films[i]`."],"trace":""},{"id":"A5","n":5,"pts":0.75,"title":"Зрители двух залов","topics":"множества, симметричная разность","text":"Две строки: имена зрителей первого зала и второго (через пробел).\n\nНапечатайте, сколько людей побывало **ровно в одном** из залов (то есть не в обоих).","fin":"Две строки, имена через пробел.","fout":"Одно число.","pre":"","tests":[{"i":"Аня Борис Вера\nБорис Глеб","o":"3"},{"i":"Омск\nОмск","o":"0"},{"i":"А Б В\nГ Д","o":"5"},{"i":"Зоя\nЗоя Ира Лев","o":"2"},{"i":"Паша Рита\nРита Паша","o":"0"}],"sol":"first = set(input().split())\nsecond = set(input().split())\n\nprint(len(first ^ second))","hint":"Превратите обе строки во множества. «Ровно в одном» — симметрическая разность `^`.","idea":"Симметрическая разность хранит тех, кто есть только в одном из двух множеств.","steps":["`set(input().split())` — строка → список → множество.","`first ^ second` — элементы, которые есть в одном множестве, но не в обоих.","`len(...)` — сколько их."],"mist":["`|` вместо `^`: посчитаются и те, кто был в обоих залах.","`&` вместо `^`: получатся только те, кто был в обоих.","Сложили `len(first) + len(second)`: общий зритель посчитается дважды."],"trace":""},{"id":"A6","n":6,"pts":1.25,"title":"Блюда только первого стола","topics":"множества, разность и пересечение","text":"Три строки с названиями блюд через запятую **без пробела** (в названиях пробелы бывают): заказ первого стола; заказ второго стола; меню кафе.\n\nНапечатайте, сколько блюд заказал **только первый стол** (второй их не брал) и которые **есть в меню**.","fin":"Три строки, блюда через запятую.","fout":"Одно число.","pre":"","tests":[{"i":"Борщ,Суп,Чай\nЧай,Пирог\nБорщ,Суп,Чай,Пирог","o":"2"},{"i":"Салат,Хлеб\nСалат\nСалат,Хлеб","o":"1"},{"i":"Х\nХ\nХ","o":"0"},{"i":"Пицца,Паста\nКофе\nПаста,Кофе","o":"1"},{"i":"Рыба фри,Чай\nЧай\nЧай,Рыба фри,Торт","o":"1"}],"sol":"first = set(input().split(','))\nsecond = set(input().split(','))\nmenu = set(input().split(','))\n\nonly = first - second\nprint(len(only & menu))","hint":"«Только первый стол» — разность `-`. Потом пересеките результат `&` с меню.","idea":"Сначала блюда первого стола, которых нет у второго (`-`), затем оставляем только те, что есть в меню (`&`).","steps":["Разделитель — запятая без пробела: `.split(\",\")`. Без аргумента названия с пробелами разорвутся.","`first - second` — блюда первого стола, которых нет у второго.","`only & menu` — из них только те, что есть в меню.","`len(...)` — сколько их."],"mist":["`split()` вместо `split(\",\")`: «Рыба фри» разорвётся на два блюда.","`second - first` вместо `first - second`: получится про второй стол.","`^` вместо `-`: попадут и блюда, которые брал только второй стол."],"trace":""},{"id":"A7","n":7,"pts":0.75,"title":"Блюда в рамках бюджета","topics":"словарь, перебор ключей","text":"В окне задан словарь `menu`: блюдо → цена. Вводится бюджет (целое число).\n\nНапечатайте блюда, цена которых **не больше** бюджета, каждое с новой строки, в порядке словаря. Если таких нет, ничего не печатайте.","fin":"Одна строка — бюджет (целое число).","fout":"Названия по одному на строке или пустой вывод.","pre":"menu = {'чай': 80, 'кофе': 150, 'борщ': 250, 'стейк': 900, 'салат': 220, 'пирог': 130}","tests":[{"i":"150","o":"чай\nкофе\nпирог"},{"i":"80","o":"чай"},{"i":"1000","o":"чай\nкофе\nборщ\nстейк\nсалат\nпирог"},{"i":"50","o":""},{"i":"220","o":"чай\nкофе\nсалат\nпирог"}],"sol":"budget = int(input())\n\nfor dish in menu:\n    if menu[dish] <= budget:\n        print(dish)","hint":"Цикл `for dish in menu` перебирает **ключи** (блюда). Цена берётся как `menu[dish]`. Введённый бюджет — строка, нужен `int`.","idea":"Идём по блюдам и печатаем те, у которых цена не больше бюджета.","steps":["`budget = int(input())` — цены в словаре числа, значит и бюджет нужно сделать числом.","`for dish in menu:` — переменная `dish` по очереди получает каждое блюдо.","`menu[dish] <= budget` — «не больше», то есть `<=`.","Печатаем `dish`, а не цену."],"mist":["Забыли `int(...)`: сравнение `80 <= \"150\"` — ошибка `TypeError`.","`<` вместо `<=`: блюдо с ценой ровно как бюджет пропадёт.","Напечатали `menu[dish]`: получится цена вместо названия."],"trace":""},{"id":"A8","n":8,"pts":1.25,"title":"Столы с хорошими чаевыми","topics":"словарь списков, sum","text":"В окне задан словарь `tables`: стол → список чаевых за четыре дня (в рублях). Вводится порог.\n\nНапечатайте столы, у которых **сумма** чаевых **строго больше** порога, каждый с новой строки, в порядке словаря.","fin":"Одна строка — порог (целое число).","fout":"Названия столов по одному на строке или пустой вывод.","pre":"tables = {'Первый': [100, 250, 0, 300], 'Второй': [50, 40, 60, 30], 'Третий': [500, 100, 200, 400], 'Четвёртый': [120, 130, 100, 150]}","tests":[{"i":"300","o":"Первый\nТретий\nЧетвёртый"},{"i":"180","o":"Первый\nТретий\nЧетвёртый"},{"i":"650","o":"Третий"},{"i":"1200","o":""},{"i":"0","o":"Первый\nВторой\nТретий\nЧетвёртый"}],"sol":"limit = int(input())\n\nfor table in tables:\n    if sum(tables[table]) > limit:\n        print(table)","hint":"Сумма чаевых стола — `sum(tables[table])`. Сравните её с порогом.","idea":"Для каждого ключа берём список, считаем сумму и сравниваем с порогом.","steps":["`tables[table]` — список чаевых стола.","`sum(...)` — сумма за четыре дня.","`> limit` — строго больше порога.","Печатаем `table`, а не сумму."],"mist":["Сравнили `tables[table] > limit`: список с числом сравнивать нельзя.","`>=` вместо `>`: стол с суммой ровно как порог попадёт зря.","Напечатали `sum(...)` вместо названия стола."],"trace":"Первый: 100 + 250 + 0 + 300 = 650. Второй: 180. Третий: 1200. Четвёртый: 500. При пороге 300 строго больше у Первого, Третьего и Четвёртого."},{"id":"A9","n":9,"pts":1.5,"title":"Длительность фильмов","topics":"цикл, f-строка, // и %","text":"В одной строке длительности фильмов в минутах, через пробел.\n\nДля каждого фильма напечатайте строку в формате `H ч M мин`, где `H` — целые часы, `M` — оставшиеся минуты. Фильмы — в порядке ввода, каждый с новой строки.","fin":"Одна строка — минуты через пробел.","fout":"По строке `H ч M мин` на каждый фильм.","pre":"","tests":[{"i":"95 120 200","o":"1 ч 35 мин\n2 ч 0 мин\n3 ч 20 мин"},{"i":"59","o":"0 ч 59 мин"},{"i":"60 61","o":"1 ч 0 мин\n1 ч 1 мин"},{"i":"180","o":"3 ч 0 мин"},{"i":"45 90 135 1","o":"0 ч 45 мин\n1 ч 30 мин\n2 ч 15 мин\n0 ч 1 мин"}],"sol":"minutes = input().split()\n\nfor m in minutes:\n    print(f'{int(m) // 60} ч {int(m) % 60} мин')","hint":"Часы — `// 60`, минуты — `% 60`. Число бывает строкой, нужен `int`. Печатайте через f-строку.","idea":"Для каждой длительности делим на 60 нацело (часы) и берём остаток (минуты).","steps":["`minutes` — список **строк**, берём `int(m)`.","`int(m) // 60` — целые часы, `int(m) % 60` — остаток минут.","f-строка подставляет оба значения в шаблон `H ч M мин`."],"mist":["Забыли `int`: `//` и `%` со строкой — ошибка.","Поставили `/` вместо `//`: часы получатся дробными.","Напечатали все фильмы одной строкой: нужен отдельный `print` на каждый."],"trace":"95 минут: 95 // 60 = 1, 95 % 60 = 35 → `1 ч 35 мин`. 120: 2 и 0 → `2 ч 0 мин`. 200: 3 и 20."},{"id":"A10","n":10,"pts":1.5,"title":"Рейтинг блюд","topics":"while True, словарь-накопитель, sorted и lambda","text":"Вводятся строки вида `блюдо,порций` (число порций — целое **положительное**), пока не будет введено слово `END`. Одно блюдо может встретиться несколько раз.\n\nНапечатайте блюда по **убыванию** суммарного числа порций, при равенстве — по алфавиту. Каждое — с новой строки в виде `блюдо порций`.","fin":"Строки `блюдо,порций`, последняя строка — `END`.","fout":"Строки `блюдо порций`.","pre":"","tests":[{"i":"борщ,10\nсуп,15\nборщ,10\nчай,5\nEND","o":"борщ 20\nсуп 15\nчай 5"},{"i":"пицца,7\nEND","o":"пицца 7"},{"i":"б,10\nа,10\nв,3\nEND","o":"а 10\nб 10\nв 3"},{"i":"чай,5\nкофе,5\nчай,1\nEND","o":"чай 6\nкофе 5"}],"sol":"totals = {}\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    dish, count = line.split(',')\n    if dish in totals:\n        totals[dish] += int(count)\n    else:\n        totals[dish] = int(count)\n\nfor dish, count in sorted(totals.items(), key=lambda x: (-x[1], x[0])):\n    print(dish, count)","hint":"Сначала накопите суммы в словаре, как в предыдущих задачах. Потом `sorted(totals.items(), key=lambda x: (-x[1], x[0]))`.","idea":"Сначала словарь «блюдо → порций», потом сортировка пар: минус перед числом даёт убывание, второе значение кортежа — алфавит при равенстве.","steps":["`totals = {}` — до цикла.","Если блюдо уже есть, прибавляем `totals[dish] += int(count)`, иначе создаём запись.","`totals.items()` — пары (блюдо, порций).","`key=lambda x: (-x[1], x[0])` — сначала по убыванию порций, потом по алфавиту.","`print(dish, count)` — через пробел."],"mist":["Забыли `-` перед `x[1]`: порядок будет по возрастанию.","Сортировка только по значению: при равенстве порядок блюд не алфавитный.","Забыли `int(count)`: строки склеиваются, а не складываются."],"trace":"Борщ: 10 + 10 = 20, суп: 15, чай: 5. По убыванию: борщ 20, суп 15, чай 5."}]},{"id":"B","name":"Вариант Б","sub":"Спорт и зоопарк","tasks":[{"id":"B1","n":1,"pts":0.5,"title":"Вход в спортзал","topics":"if / elif / else, not in, and","text":"В окне уже заданы список `members` и три фразы: `guest_msg`, `bonus_msg`, `usual_msg`. Вводятся имя посетителя и число его посещений за месяц.\n\nЕсли имени нет в списке членов клуба, напечатайте `guest_msg`. Если посетитель в списке и был не меньше 10 раз, напечатайте `bonus_msg`. Во всех остальных случаях напечатайте `usual_msg`.","fin":"Первая строка — имя, вторая — число посещений (целое).","fout":"Одна из трёх фраз.","pre":"members = ['Аня', 'Борис', 'Вера']\nguest_msg = 'Гостевой вход'\nbonus_msg = 'Бонус за активность'\nusual_msg = 'Обычный вход'","tests":[{"i":"Аня\n12","o":"Бонус за активность"},{"i":"Борис\n3","o":"Обычный вход"},{"i":"Глеб\n20","o":"Гостевой вход"},{"i":"Вера\n10","o":"Бонус за активность"},{"i":"Аня\n9","o":"Обычный вход"},{"i":"аня\n15","o":"Гостевой вход"}],"sol":"name = input()\nvisits = int(input())\n\nif name not in members:\n    print(guest_msg)\nelif visits >= 10:\n    print(bonus_msg)\nelse:\n    print(usual_msg)","hint":"Сначала отсеките тех, кого нет в списке (`not in`), потом проверьте посещения. «Не меньше 10» — это `>=`. Не забудьте `int`.","idea":"Три исхода — цепочка `if / elif / else`: не член клуба; член с бонусом; член без бонуса.","steps":["`name = input()` читает имя, `visits = int(input())` читает число и сразу делает его числом.","`name not in members` — первая проверка: если человека нет, остальное не важно.","`visits >= 10` выполняется только когда он в списке; «не меньше» — это `>=`.","`else` — обычный вход."],"mist":["Поставили `>` вместо `>=`: посетитель с ровно 10 посещениями не получит бонус.","Забыли `int(...)`: сравнение строки с числом — ошибка `TypeError`.","Регистр важен: `аня` не равно `Аня`, такого члена клуба нет."],"trace":""},{"id":"B2","n":2,"pts":1,"title":"Быстрые бегуны","topics":"while True, break, split, список","text":"Вводятся строки вида `имя:секунд` (время забега, целое число), пока не будет введено слово `END`.\n\nНапечатайте список бегунов, которые пробежали **быстрее 60 секунд** (строго), в порядке ввода. Если таких нет, напечатайте пустой список.","fin":"Строки `имя:секунд`, последняя строка — `END`.","fout":"Список имён в квадратных скобках, как печатает `print(список)`.","pre":"","tests":[{"i":"Аня:55\nБорис:60\nВера:61\nEND","o":"['Аня']"},{"i":"END","o":"[]"},{"i":"Глеб:59\nДаша:30\nEND","o":"['Глеб', 'Даша']"},{"i":"Егор:100\nEND","o":"[]"},{"i":"Зоя:60\nEND","o":"[]"}],"sol":"fast = []\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    name, seconds = line.split(':')\n    if int(seconds) < 60:\n        fast.append(name)\n\nprint(fast)","hint":"Список создайте до цикла. Строку режьте по двоеточию: `name, seconds = line.split(\":\")`. Время — строка, нужен `int`. «Быстрее» — это `<`.","idea":"Читаем строки в бесконечном цикле, на слове `END` выходим через `break`, остальное разбираем и фильтруем.","steps":["`fast = []` создаём **до** цикла, иначе список обнулялся бы на каждой строке.","`while True:` — читаем, пока сами не прервём цикл.","`line == \"END\"` → `break`: выходим, не обрабатывая слово `END`.","`name, seconds = line.split(\":\")` — две части строки в две переменные.","`int(seconds) < 60` — «быстрее» строго, ровно 60 не подходит."],"mist":["Список создан внутри цикла — в конце останется только последний бегун.","Не сделали `int(seconds)`: сравнение строки с числом — ошибка `TypeError`.","Поставили `<=`: бегун ровно на 60 секунд попадёт зря."],"trace":""},{"id":"B3","n":3,"pts":0.5,"title":"Новое животное","topics":"split(\", \"), in, append","text":"В первой строке названия животных зоопарка через «запятая + пробел». Во второй — название нового животного.\n\nЕсли оно уже есть в зоопарке, напечатайте `Уже есть`. Если его нет — добавьте в конец списка и напечатайте список.","fin":"Первая строка — животные через `, `. Вторая — одно название.","fout":"Фраза `Уже есть` или список названий в квадратных скобках.","pre":"","tests":[{"i":"тигр, лев, слон\nзебра","o":"['тигр', 'лев', 'слон', 'зебра']"},{"i":"тигр, лев\nлев","o":"Уже есть"},{"i":"панда\nпанда","o":"Уже есть"},{"i":"жираф, зебра\nбегемот","o":"['жираф', 'зебра', 'бегемот']"},{"i":"тигр\nТигр","o":"['тигр', 'Тигр']"}],"sol":"animals = input().split(', ')\nnew_animal = input()\n\nif new_animal in animals:\n    print('Уже есть')\nelse:\n    animals.append(new_animal)\n    print(animals)","hint":"Строку разбейте `split(\", \")`. Если животное есть (`in`) — печатаем фразу, иначе `append` и печатаем список.","idea":"Превращаем строку в список, проверяем наличие и выбираем между двумя выводами.","steps":["`input().split(\", \")` — строка превращается в список названий.","`new_animal in animals` — истина, если такое животное уже есть.","Если есть — только фраза; иначе `append` и печать списка.","Обе печати внутри своей ветки `if` / `else`."],"mist":["`split()` без аргумента: запятые останутся в кусках названий.","Напечатали список вне `else`: в первом случае вывод будет лишним.","Регистр важен: `Тигр` и `тигр` — разные названия."],"trace":""},{"id":"B4","n":4,"pts":1,"title":"Тяжёлые животные","topics":"два списка, range(len())","text":"В первой строке названия животных через пробел, во второй — их вес в килограммах (целые числа) в том же порядке. В третьей — предельный вес.\n\nНапечатайте названия животных, чей вес **строго больше** предельного, каждое с новой строки.","fin":"Три строки: названия, веса, предельный вес.","fout":"Названия по одному на строке или пустой вывод.","pre":"","tests":[{"i":"слон тигр заяц бегемот\n4000 200 5 1500\n1000","o":"слон\nбегемот"},{"i":"А Б\n10 20\n50","o":""},{"i":"Один\n300\n299","o":"Один"},{"i":"Х У Ф\n40 50 60\n50","o":"Ф"},{"i":"Лев Волк\n190 40\n10","o":"Лев\nВолк"}],"sol":"animals = input().split()\nweights = input().split()\nlimit = int(input())\n\nfor i in range(len(animals)):\n    if int(weights[i]) > limit:\n        print(animals[i])","hint":"Животные и веса лежат в двух списках, связь — одинаковый номер. Переберите номера через `range(len(...))`. Веса — строки, нужен `int`.","idea":"Идём по номерам: по номеру берём и животное, и вес, сравниваем вес с предельным.","steps":["`animals` и `weights` — списки **строк**; вес берём как `int(weights[i])`.","`range(len(animals))` — номера 0, 1, 2, …","`int(weights[i]) > limit` — «строго больше», то есть `>`.","Печатаем `animals[i]` — животное с тем же номером."],"mist":["`>=` вместо `>`: животное с весом ровно как предельный попадёт зря.","Сравнили `weights[i] > limit` без `int`: строка с числом — ошибка `TypeError`.","Напечатали `weights[i]` вместо `animals[i]`."],"trace":""},{"id":"B5","n":5,"pts":0.75,"title":"Все виды спорта","topics":"множества, объединение","text":"Две строки: виды спорта первой секции и второй (через пробел).\n\nНапечатайте, сколько **различных** видов спорта в двух секциях вместе.","fin":"Две строки, названия через пробел.","fout":"Одно число.","pre":"","tests":[{"i":"футбол теннис бокс\nбокс плавание","o":"4"},{"i":"йога\nйога","o":"1"},{"i":"а б в\nг д","o":"5"},{"i":"хоккей\nхоккей лыжи биатлон","o":"3"},{"i":"шахматы го\nго шахматы","o":"2"}],"sol":"first = set(input().split())\nsecond = set(input().split())\n\nprint(len(first | second))","hint":"Превратите обе строки во множества. «Вместе, без повторов» — это объединение `|`.","idea":"Объединение двух множеств хранит каждый вид спорта один раз, даже если он есть в обеих секциях.","steps":["`set(input().split())` — строка → список → множество.","`first | second` — виды спорта хотя бы одной секции, без повторов.","`len(...)` — сколько их."],"mist":["Сложили `len(first) + len(second)`: общий вид спорта посчитается дважды.","`&` вместо `|`: получатся только виды, общие для обеих секций.","`first + second`: сложение множеств не работает, будет `TypeError`."],"trace":""},{"id":"B6","n":6,"pts":1.25,"title":"Новые секции","topics":"множества, объединение и разность","text":"Три строки с названиями видов спорта через запятую **без пробела** (в названиях пробелы бывают): секция А; секция Б; виды спорта, которые уже есть в школе.\n\nНапечатайте, сколько видов спорта есть в секции А **или** Б, но **нет в школе**.","fin":"Три строки, виды через запятую.","fout":"Одно число.","pre":"","tests":[{"i":"футбол,теннис\nтеннис,бокс\nфутбол","o":"2"},{"i":"конный спорт,йога\nйога\nйога","o":"1"},{"i":"Х\nХ\nХ","o":"0"},{"i":"плавание\nлыжи,биатлон\nшахматы","o":"3"},{"i":"дзюдо,самбо\nсамбо,каратэ\nдзюдо,каратэ,сумо","o":"1"}],"sol":"first = set(input().split(','))\nsecond = set(input().split(','))\nschool = set(input().split(','))\n\nsections = first | second\nprint(len(sections - school))","hint":"Сначала объедините секции `|`, потом вычтите `-` виды, которые уже есть в школе.","idea":"Собираем все виды спорта двух секций (объединение) и вычитаем те, что уже есть в школе.","steps":["Разделитель — запятая без пробела: `.split(\",\")`. Без аргумента названия с пробелами разорвутся.","`first | second` — виды спорта хотя бы одной секции.","`sections - school` — те из них, которых нет в школе.","`len(...)` — сколько их."],"mist":["`split()` вместо `split(\",\")`: «конный спорт» разорвётся на два вида.","Вычли в другую сторону `school - sections`: получится совсем другое множество.","`&` вместо `|` в первом шаге: получатся виды, которые есть в обеих секциях."],"trace":""},{"id":"B7","n":7,"pts":0.75,"title":"Животные вольера","topics":"словарь, перебор ключей","text":"В окне задан словарь `cages`: животное → номер вольера (число). Вводится номер вольера.\n\nНапечатайте животных из этого вольера, каждое с новой строки, в порядке словаря. Если таких нет, ничего не печатайте.","fin":"Одна строка — номер вольера (целое число).","fout":"Названия по одному на строке или пустой вывод.","pre":"cages = {'тигр': 1, 'лев': 1, 'зебра': 2, 'жираф': 2, 'слон': 3, 'бегемот': 3, 'панда': 4}","tests":[{"i":"1","o":"тигр\nлев"},{"i":"2","o":"зебра\nжираф"},{"i":"3","o":"слон\nбегемот"},{"i":"4","o":"панда"},{"i":"9","o":""}],"sol":"number = int(input())\n\nfor animal in cages:\n    if cages[animal] == number:\n        print(animal)","hint":"Цикл `for animal in cages` перебирает **ключи** (животных). Номер вольера берётся как `cages[animal]`. Введённый номер — строка, нужен `int`.","idea":"Идём по животным и печатаем тех, у кого номер вольера совпадает с введённым.","steps":["`number = int(input())` — номера в словаре числа, значит и введённое нужно сделать числом.","`for animal in cages:` — переменная `animal` по очереди получает каждое животное.","`cages[animal] == number` — совпадение номера.","Печатаем `animal`, а не номер."],"mist":["Забыли `int(...)`: `1 == \"1\"` даёт `False`, и ничего не напечатается.","Напечатали `cages[animal]`: получится номер вольера вместо животного.","Ждали, что цикл даст значения: он перебирает ключи."],"trace":""},{"id":"B8","n":8,"pts":1.25,"title":"Спортсмены с рекордом","topics":"словарь списков, min","text":"В окне задан словарь `athletes`: спортсмен → список времён забегов в секундах. Вводится норматив.\n\nНапечатайте спортсменов, у которых **хотя бы один** забег был **быстрее** норматива (строго меньше), каждого с новой строки, в порядке словаря.","fin":"Одна строка — норматив (целое число).","fout":"Имена по одному на строке или пустой вывод.","pre":"athletes = {'Аня': [62, 58, 60], 'Борис': [70, 72, 69], 'Вера': [55, 57, 56], 'Глеб': [61, 63, 64]}","tests":[{"i":"60","o":"Аня\nВера"},{"i":"56","o":"Вера"},{"i":"70","o":"Аня\nБорис\nВера\nГлеб"},{"i":"50","o":""},{"i":"100","o":"Аня\nБорис\nВера\nГлеб"}],"sol":"limit = int(input())\n\nfor athlete in athletes:\n    if min(athletes[athlete]) < limit:\n        print(athlete)","hint":"«Хотя бы один забег быстрее» — это то же, что «лучшее время меньше норматива». Используйте `min`.","idea":"Вместо проверки каждого забега сравниваем с нормативом минимум в списке.","steps":["`athletes[athlete]` — список времён спортсмена.","`min(...)` — лучшее (самое маленькое) время.","Если лучшее время меньше норматива, то хотя бы один забег подходит. Строго «меньше» — это `<`.","Печатаем **ключ** `athlete`, а не список."],"mist":["`max` вместо `min`: условие станет «все забеги быстрее норматива».","`<=` вместо `<`: спортсмен с лучшим временем ровно в норматив попадёт зря.","Напечатали `athletes[athlete]` — список вместо имени."],"trace":""},{"id":"B9","n":9,"pts":1.5,"title":"Автобусы для групп","topics":"цикл, //, %, if","text":"Первая строка — число человек в каждой группе экскурсантов, через пробел. Вторая — вместимость одного автобуса (целое число). Каждая группа едет отдельно, свободные места другим группам не отдаются.\n\nНапечатайте, сколько автобусов понадобится на все группы.","fin":"Две строки: размеры групп, вместимость автобуса.","fout":"Одно число.","pre":"","tests":[{"i":"25 40 10\n20","o":"5"},{"i":"7\n10","o":"1"},{"i":"100 100\n25","o":"8"},{"i":"1 2 3\n2","o":"4"},{"i":"50\n7","o":"8"}],"sol":"groups = input().split()\ncapacity = int(input())\n\nbuses = 0\nfor group in groups:\n    buses += int(group) // capacity\n    if int(group) % capacity != 0:\n        buses += 1\n\nprint(buses)","hint":"Для одной группы полные автобусы — `//`. Если остаток `%` не ноль, нужен ещё один автобус. Счётчик создайте до цикла.","idea":"Для каждой группы считаем полные автобусы делением нацело и добавляем ещё один, если кто-то остался.","steps":["`groups` — список **строк**, каждую берём как `int(group)`.","`int(group) // capacity` — полные автобусы.","`int(group) % capacity != 0` — остались люди, нужен ещё автобус.","`buses = 0` до цикла, печатаем после."],"mist":["Только `//` без проверки остатка: неполный автобус потеряется.","Обнулили счётчик внутри цикла: останутся данные последней группы.","Забыли `int(group)`: деление `//` со строкой — ошибка."],"trace":"Группы `25 40 10`, автобус на 20: 25 → 1 полный и остаток 5, значит 2; 40 → 2 полных, остатка нет, значит 2; 10 → 0 полных, остаток 10, значит 1. Итого 5."},{"id":"B10","n":10,"pts":1.5,"title":"Самый слабый игрок","topics":"while True, словарь-накопитель, минимум","text":"Вводятся строки вида `игрок,очки` (очки — целое **положительное** число), пока не будет введено слово `END`. Один игрок может встретиться несколько раз.\n\nНайдите игрока с **наименьшей суммой** очков. Напечатайте его имя и сумму через пробел. Гарантируется, что есть хотя бы одна строка. Если таких несколько, выберите того, кто встретился в списке раньше.","fin":"Строки `игрок,очки`, последняя строка — `END`.","fout":"Имя и число через пробел.","pre":"","tests":[{"i":"Аня,10\nБорис,4\nАня,15\nБорис,6\nВера,25\nEND","o":"Борис 10"},{"i":"Глеб,5\nEND","o":"Глеб 5"},{"i":"А,10\nБ,10\nEND","o":"А 10"},{"i":"Х,100\nУ,50\nУ,60\nEND","o":"Х 100"},{"i":"Д,3\nЕ,2\nД,1\nЕ,7\nEND","o":"Д 4"}],"sol":"totals = {}\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    player, points = line.split(',')\n    if player in totals:\n        totals[player] += int(points)\n    else:\n        totals[player] = int(points)\n\nworst = ''\nfor player in totals:\n    if worst == '' or totals[player] < totals[worst]:\n        worst = player\n\nprint(worst, totals[worst])","hint":"Два шага: (1) в цикле копите суммы в словаре; (2) после цикла найдите минимум. Первого игрока берите как стартового, для равных сумм сравнивайте строго `<`.","idea":"Сначала собираем словарь «игрок → сумма», потом ищем ключ с наименьшим значением.","steps":["`totals = {}` — до цикла.","Если игрок уже есть, прибавляем `totals[player] += int(points)`, иначе создаём запись.","`worst = \"\"` — пока никого не выбрали; `worst == \"\"` берёт первого игрока без сравнения.","`<` (строго) оставляет первого из равных.","Печатаем после цикла имя и его сумму."],"mist":["Стартовое значение `0` вместо проверки пустого имени: ни одна сумма не окажется меньше нуля.","`min(totals)` без `key` берёт минимум **по алфавиту имён**, а не по сумме.","`<=` вместо `<`: при равных суммах выберется последний, а не первый."],"trace":"Аня: 10 + 15 = 25, Борис: 4 + 6 = 10, Вера: 25. Минимум 10 у Бориса. Ответ `Борис 10`."}]},{"id":"C","name":"Вариант В","sub":"Университет и склад","tasks":[{"id":"C1","n":1,"pts":0.5,"title":"Вход в общежитие","topics":"if / elif / else, not in, or","text":"В окне уже заданы список `students` и три фразы: `stranger_msg`, `late_msg`, `ok_msg`. Вводятся имя и час возвращения (целое число от 0 до 23).\n\nЕсли имени нет в списке студентов, напечатайте `stranger_msg`. Если студент в списке и вернулся в 23 часа или позже, либо раньше 6 утра, напечатайте `late_msg`. Во всех остальных случаях напечатайте `ok_msg`.","fin":"Первая строка — имя, вторая — час (целое число).","fout":"Одна из трёх фраз.","pre":"students = ['Аня', 'Борис', 'Вера']\nstranger_msg = 'Посторонним вход запрещён'\nlate_msg = 'Запишем в журнал опозданий'\nok_msg = 'Проходите'","tests":[{"i":"Аня\n22","o":"Проходите"},{"i":"Борис\n23","o":"Запишем в журнал опозданий"},{"i":"Глеб\n12","o":"Посторонним вход запрещён"},{"i":"Вера\n5","o":"Запишем в журнал опозданий"},{"i":"Аня\n6","o":"Проходите"},{"i":"Борис\n0","o":"Запишем в журнал опозданий"}],"sol":"name = input()\nhour = int(input())\n\nif name not in students:\n    print(stranger_msg)\nelif hour >= 23 or hour < 6:\n    print(late_msg)\nelse:\n    print(ok_msg)","hint":"Сначала отсеките посторонних (`not in`), потом проверьте час через `or`, остальное — `else`. Час — строка, нужен `int`.","idea":"Три исхода — цепочка `if / elif / else`: нет в списке; поздно или слишком рано; нормальное время.","steps":["`name = input()` читает имя, `hour = int(input())` читает час и сразу делает его числом.","`name not in students` — первая проверка: если человека нет, час не важен.","`hour >= 23 or hour < 6` — поздно, если верно **хотя бы одно** из двух условий.","`else` — можно проходить."],"mist":["Написали `hour >= 23 and hour < 6`: оба условия сразу не бывают верны, опоздавших не будет.","Забыли `int(...)`: сравнение строки с числом — ошибка `TypeError`.","Границы: 23 — уже поздно, 6 — ещё можно; перепутали `>=` и `>`."],"trace":""},{"id":"C2","n":2,"pts":1,"title":"Сданные предметы","topics":"while True, break, split, список","text":"Вводятся строки вида `предмет:балл` (балл — целое число), пока не будет введено слово `END`.\n\nНапечатайте список предметов, по которым балл **не ниже 60**, в порядке ввода. Если таких нет, напечатайте пустой список.","fin":"Строки `предмет:балл`, последняя строка — `END`.","fout":"Список предметов в квадратных скобках, как печатает `print(список)`.","pre":"","tests":[{"i":"Python:85\nСтатистика:59\nАнглийский:60\nEND","o":"['Python', 'Английский']"},{"i":"END","o":"[]"},{"i":"Матан:40\nФизика:30\nEND","o":"[]"},{"i":"История:100\nПраво:75\nEND","o":"['История', 'Право']"},{"i":"Химия:60\nEND","o":"['Химия']"}],"sol":"passed = []\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    subject, mark = line.split(':')\n    if int(mark) >= 60:\n        passed.append(subject)\n\nprint(passed)","hint":"Список создайте до цикла. Строку режьте по двоеточию: `subject, mark = line.split(\":\")`. Балл — строка, нужен `int`. «Не ниже» — это `>=`.","idea":"Читаем строки в бесконечном цикле, на слове `END` выходим через `break`, остальное разбираем и фильтруем.","steps":["`passed = []` создаём **до** цикла, иначе список обнулялся бы на каждой строке.","`while True:` — читаем, пока сами не прервём цикл.","`line == \"END\"` → `break`: выходим, не обрабатывая слово `END`.","`subject, mark = line.split(\":\")` — две части строки в две переменные.","`int(mark) >= 60` — «не ниже» включает ровно 60."],"mist":["Список создан внутри цикла — в конце останется только последний предмет.","Не сделали `int(mark)`: сравнение строки с числом — ошибка `TypeError`.","Поставили `>`: предмет ровно с 60 баллами пропадёт."],"trace":""},{"id":"C3","n":3,"pts":0.5,"title":"Выдача со склада","topics":"split(\", \"), in, remove","text":"В первой строке товары на складе через «запятая + пробел». Во второй — название товара, который нужно выдать.\n\nЕсли он есть на складе, удалите его из списка и напечатайте список. Если его нет — напечатайте `Нет на складе`.","fin":"Первая строка — товары через `, `. Вторая — одно название.","fout":"Список товаров в квадратных скобках или фраза `Нет на складе`.","pre":"","tests":[{"i":"мышь, клавиатура, монитор\nклавиатура","o":"['мышь', 'монитор']"},{"i":"мышь, монитор\nкабель","o":"Нет на складе"},{"i":"лампа\nлампа","o":"[]"},{"i":"стол, стул\nСтол","o":"Нет на складе"},{"i":"ручка, блокнот, папка\nпапка","o":"['ручка', 'блокнот']"}],"sol":"goods = input().split(', ')\nname = input()\n\nif name in goods:\n    goods.remove(name)\n    print(goods)\nelse:\n    print('Нет на складе')","hint":"Строку разбейте `split(\", \")`. Если товар есть (`in`) — `remove` и печать списка, иначе печатаем фразу.","idea":"Превращаем строку в список и по наличию товара выбираем: удалить и показать остаток или сообщить, что товара нет.","steps":["`input().split(\", \")` — строка превращается в список товаров.","`name in goods` — истина, если товар есть.","`goods.remove(name)` удаляет товар и меняет сам список.","Фраза `Нет на складе` печатается только в `else`."],"mist":["`remove` для товара, которого нет, даёт `ValueError` — поэтому сначала `in`.","Результат `remove` присвоили переменной: получится `None`.","Регистр важен: `Стол` и `стол` — разные названия."],"trace":""},{"id":"C4","n":4,"pts":1,"title":"Что пора заказать","topics":"два списка, range(len())","text":"В первой строке названия товаров через пробел, во второй — остатки на складе (целые числа) в том же порядке. В третьей — минимальный запас.\n\nНапечатайте названия товаров, остаток которых **меньше** минимального запаса (строго), каждое с новой строки.","fin":"Три строки: названия, остатки, минимальный запас.","fout":"Названия по одному на строке или пустой вывод.","pre":"","tests":[{"i":"мышь кабель стол лампа\n5 50 2 10\n10","o":"мышь\nстол"},{"i":"А Б\n100 200\n50","o":""},{"i":"Один\n9\n10","o":"Один"},{"i":"Х У Ф\n10 5 20\n10","o":"У"},{"i":"Папка Ручка\n1 0\n5","o":"Папка\nРучка"}],"sol":"goods = input().split()\nleft = input().split()\nmin_count = int(input())\n\nfor i in range(len(goods)):\n    if int(left[i]) < min_count:\n        print(goods[i])","hint":"Названия и остатки лежат в двух списках, связь — одинаковый номер. Переберите номера через `range(len(...))`. Остатки — строки, нужен `int`.","idea":"Идём по номерам: по номеру берём и товар, и остаток, сравниваем остаток с минимальным запасом.","steps":["`goods` и `left` — списки **строк**; остаток берём как `int(left[i])`.","`range(len(goods))` — номера 0, 1, 2, …","`int(left[i]) < min_count` — «меньше», то есть `<`.","Печатаем `goods[i]` — товар с тем же номером."],"mist":["`<=` вместо `<`: товар с остатком ровно как запас попадёт зря.","Сравнили `left[i] < min_count` без `int`: строка с числом — ошибка `TypeError`.","Напечатали `left[i]` вместо `goods[i]`."],"trace":""},{"id":"C5","n":5,"pts":0.75,"title":"Общие студенты","topics":"множества, пересечение","text":"Две строки: имена студентов группы по Python и группы по статистике (через пробел).\n\nНапечатайте, сколько студентов учится **в обеих** группах.","fin":"Две строки, имена через пробел.","fout":"Одно число.","pre":"","tests":[{"i":"Аня Борис Вера\nВера Глеб Аня","o":"2"},{"i":"Омск\nОмск","o":"1"},{"i":"А Б В\nГ Д","o":"0"},{"i":"Зоя\nЗоя Ира Лев","o":"1"},{"i":"Паша Рита\nСергей Тоня","o":"0"}],"sol":"python = set(input().split())\nstatistics = set(input().split())\n\nprint(len(python & statistics))","hint":"Превратите обе строки во множества. «В обеих группах» — пересечение `&`.","idea":"Пересечение двух множеств хранит тех, кто есть и в первом, и во втором.","steps":["`set(input().split())` — строка → список → множество.","`python & statistics` — студенты обеих групп.","`len(...)` — сколько их."],"mist":["`|` вместо `&`: посчитаются все студенты хотя бы одной группы.","Сложили `len(python) + len(statistics)`: общий студент посчитается дважды.","`print(python & statistics)` печатает множество, а нужно число."],"trace":""},{"id":"C6","n":6,"pts":1.25,"title":"Только Python и статистика","topics":"множества, пересечение и разность","text":"Три строки с названиями курсов через запятую **без пробела**, которые посещает студент: Аня; Борис; Вера. Названия бывают из нескольких слов.\n\nНапечатайте, сколько курсов посещает **и Аня, и Борис, но не Вера**.","fin":"Три строки, курсы через запятую.","fout":"Одно число.","pre":"","tests":[{"i":"Python,Статистика,Английский\nPython,Английский\nСтатистика","o":"2"},{"i":"Основы ИИ,Python\nОсновы ИИ\nPython","o":"1"},{"i":"Х\nХ\nХ","o":"0"},{"i":"Право,Экономика\nПраво,Экономика,История\nЭкономика","o":"1"},{"i":"Матан\nФизика\nМатан","o":"0"}],"sol":"anna = set(input().split(','))\nboris = set(input().split(','))\nvera = set(input().split(','))\n\nboth = anna & boris\nprint(len(both - vera))","hint":"Сначала пересеките курсы Ани и Бориса `&`, потом вычтите `-` курсы Веры.","idea":"Находим общие курсы Ани и Бориса (пересечение) и убираем те, которые посещает Вера (разность).","steps":["Разделитель — запятая без пробела: `.split(\",\")`. Без аргумента названия с пробелами разорвутся.","`anna & boris` — курсы, которые посещают оба.","`both - vera` — из них те, которых нет у Веры.","`len(...)` — сколько их."],"mist":["`split()` вместо `split(\",\")`: «Основы ИИ» разорвётся на два курса.","Вычли в другую сторону `vera - both`: получится совсем другое множество.","`|` вместо `&` в первом шаге: получатся курсы хотя бы одного из двоих."],"trace":""},{"id":"C7","n":7,"pts":0.75,"title":"Студенты группы","topics":"словарь, перебор ключей","text":"В окне задан словарь `groups`: студент → название группы. Вводится название группы.\n\nНапечатайте студентов этой группы, каждого с новой строки, в порядке словаря. Если таких нет, ничего не печатайте.","fin":"Одна строка — название группы.","fout":"Имена по одному на строке или пустой вывод.","pre":"groups = {'Анна': 'БИ-1', 'Борис': 'БИ-2', 'Вера': 'БИ-1', 'Глеб': 'ЭК-1', 'Дарья': 'БИ-2', 'Егор': 'БИ-1'}","tests":[{"i":"БИ-1","o":"Анна\nВера\nЕгор"},{"i":"БИ-2","o":"Борис\nДарья"},{"i":"ЭК-1","o":"Глеб"},{"i":"ЮР-1","o":""},{"i":"би-1","o":""}],"sol":"group = input()\n\nfor student in groups:\n    if groups[student] == group:\n        print(student)","hint":"Цикл `for student in groups` перебирает **ключи** (студентов). Группа берётся как `groups[student]`.","idea":"Идём по студентам и печатаем тех, у кого группа совпадает с введённой.","steps":["`for student in groups:` — переменная `student` по очереди получает каждого студента.","`groups[student]` — группа этого студента.","`== group` — совпадение с введённым названием.","Печатаем `student`, а не группу."],"mist":["Напечатали `groups[student]`: получится название группы вместо имени.","Ждали, что цикл даст значения: он перебирает ключи.","Регистр важен: `би-1` не равно `БИ-1`."],"trace":""},{"id":"C8","n":8,"pts":1.25,"title":"Предметы с хорошей средней","topics":"словарь списков, sum / len","text":"В окне задан словарь `subjects`: предмет → список оценок группы за семестр. Вводится порог.\n\nНапечатайте предметы, у которых **средняя** оценка **не ниже** порога, каждый с новой строки, в порядке словаря.","fin":"Одна строка — порог (целое число).","fout":"Названия предметов по одному на строке или пустой вывод.","pre":"subjects = {'Python': [5, 4, 5, 4], 'Статистика': [3, 4, 3, 4], 'Английский': [5, 5, 5, 4], 'Право': [3, 3, 4, 3]}","tests":[{"i":"4","o":"Python\nАнглийский"},{"i":"5","o":""},{"i":"3","o":"Python\nСтатистика\nАнглийский\nПраво"},{"i":"2","o":"Python\nСтатистика\nАнглийский\nПраво"},{"i":"6","o":""}],"sol":"limit = int(input())\n\nfor subject in subjects:\n    average = sum(subjects[subject]) / len(subjects[subject])\n    if average >= limit:\n        print(subject)","hint":"Среднее — это `sum(список) / len(список)`. Посчитайте его для каждого предмета и сравните с порогом. «Не ниже» — `>=`.","idea":"Для каждого ключа берём список, делим сумму на длину и сравниваем среднее с порогом.","steps":["`subjects[subject]` — список оценок предмета.","`sum(...)` — сумма, `len(...)` — количество оценок; `/` даёт среднее.","`average >= limit` — не ниже порога.","Печатаем `subject`, а не среднее."],"mist":["Забыли разделить на `len(...)`: сравнится сумма, а не среднее.","Использовали `//` вместо `/`: среднее округлится вниз, и граница сдвинется.","`>` вместо `>=`: предмет со средним ровно как порог пропадёт."],"trace":"Python: 5 + 4 + 5 + 4 = 18, делим на 4 → 4,5. Статистика: 14 → 3,5. Английский: 19 → 4,75. Право: 13 → 3,25. При пороге 4 подходят Python и Английский."},{"id":"C9","n":9,"pts":1.5,"title":"Общее время лекций","topics":"цикл, // и %","text":"В одной строке длительности лекций в минутах, через пробел.\n\nНапечатайте через пробел общее время: сколько получилось целых часов и сколько осталось минут.","fin":"Одна строка — минуты через пробел.","fout":"Два числа через пробел: часы и минуты.","pre":"","tests":[{"i":"80 80 80","o":"4 0"},{"i":"59","o":"0 59"},{"i":"60 61","o":"2 1"},{"i":"90 90 90 90","o":"6 0"},{"i":"45 15","o":"1 0"}],"sol":"lectures = input().split()\n\ntotal = 0\nfor lecture in lectures:\n    total += int(lecture)\n\nprint(total // 60, total % 60)","hint":"Сложите минуты в цикле (счётчик до цикла), потом часы — `// 60`, остаток минут — `% 60`.","idea":"Сначала считаем общую сумму минут, потом переводим её в часы и минуты.","steps":["`lectures` — список **строк**, каждую берём как `int(lecture)`.","`total = 0` до цикла, в цикле `total += ...`.","`total // 60` — целые часы, `total % 60` — остаток минут.","Печатаем после цикла через запятую."],"mist":["Обнулили `total` внутри цикла: останется только последняя лекция.","Забыли `int`: строки склеятся, а не сложатся.","Поставили `/` вместо `//`: часы получатся дробными."],"trace":"Лекции `80 80 80`: сумма 240 минут, 240 // 60 = 4 часа, 240 % 60 = 0 минут. Печатаем `4 0`."},{"id":"C10","n":10,"pts":1.5,"title":"Заказы товаров","topics":"while True, словарь-накопитель, sorted","text":"Вводятся строки вида `товар,количество` (количество — целое **положительное**), пока не будет введено слово `END`. Один товар может встретиться несколько раз.\n\nНапечатайте в алфавитном порядке товары, у которых **суммарное** количество **не меньше 100**, каждый с новой строки в виде `товар количество`. Если таких нет, ничего не печатайте.","fin":"Строки `товар,количество`, последняя строка — `END`.","fout":"Строки `товар количество` или пустой вывод.","pre":"","tests":[{"i":"чай,60\nкофе,20\nчай,50\nсахар,100\nEND","o":"сахар 100\nчай 110"},{"i":"мёд,7\nEND","o":""},{"i":"б,100\nа,99\nа,1\nEND","o":"а 100\nб 100"},{"i":"Х,100\nУ,50\nУ,40\nEND","o":"Х 100"},{"i":"бумага,70\nручка,30\nбумага,30\nEND","o":"бумага 100"}],"sol":"totals = {}\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    item, count = line.split(',')\n    if item in totals:\n        totals[item] += int(count)\n    else:\n        totals[item] = int(count)\n\nfor item in sorted(totals):\n    if totals[item] >= 100:\n        print(item, totals[item])","hint":"Сначала накопите суммы в словаре. Потом переберите `sorted(totals)` (ключи по алфавиту) и печатайте те, у кого сумма `>= 100`.","idea":"Сначала словарь «товар → сумма», затем проход по ключам в алфавитном порядке с фильтром.","steps":["`totals = {}` — до цикла.","Если товар уже есть, прибавляем `totals[item] += int(count)`, иначе создаём запись.","`sorted(totals)` — ключи по алфавиту.","`totals[item] >= 100` — «не меньше», включая ровно 100.","`print(item, totals[item])` — через пробел."],"mist":["`>` вместо `>=`: товар ровно на 100 пропадёт.","Забыли `sorted`: порядок будет порядком добавления.","Забыли `int(count)`: строки склеиваются (`\"60\" + \"50\"`)."],"trace":"Чай: 60 + 50 = 110, кофе: 20, сахар: 100. По алфавиту: кофе (20, не подходит), сахар (100, подходит), чай (110, подходит). Печатаем `сахар 100` и `чай 110`."}]}];

